  add('c25',2,'own','En el ejercicio, tres tramos miden 1,2 m, 0,8 m y 1,5 m. ¿Qué suman?', ['3,5 m.','2,5 m.','3 m.','4,5 m.'], '1,2 + 0,8 + 1,5 = 3,5 m.');
  add('c26',2,'own','Se recuperan 1,5 m de un intervalo de 2 m. ¿Cuál es la recuperación?', ['75 %.','50 %.','133 %.','15 %.'], '1,5 ÷ 2 × 100 = 75 %. No rellenes el faltante con muestra de otro intervalo.');
